          elseif ($b.Shown -ne $b.Target) { $b.Shown = $b.Target; $dirty = $true }
          if ($b.Sheen -and -not $calm) { $b.Phase += 0.05; if ($b.Phase -gt $twoPi) { $b.Phase -= $twoPi }; $dirty = $true }
        }
        if ($dirty) { $b.Panel.Invalidate() }
